const state = {
  records: [],
  filterMonth: "",
  saveError: ""
};

const el = {
  date: document.getElementById("f-date"),
  type: document.getElementById("f-type"),
  category: document.getElementById("f-category"),
  categoryList: document.getElementById("category-list"),
  amount: document.getElementById("f-amount"),
  note: document.getElementById("f-note"),
  formError: document.getElementById("form-error"),
  btnAdd: document.getElementById("btn-add"),
  btnReset: document.getElementById("btn-reset"),
  month: document.getElementById("f-month"),
  btnAllMonths: document.getElementById("btn-all-months"),
  statIncome: document.getElementById("stat-income"),
  statExpense: document.getElementById("stat-expense"),
  statBalance: document.getElementById("stat-balance"),
  listHint: document.getElementById("list-hint"),
  list: document.getElementById("record-list"),
  emptyTip: document.getElementById("empty-tip"),
  dialogMask: document.getElementById("dialog-mask"),
  dialogText: document.getElementById("dialog-text"),
  dialogCancel: document.getElementById("dialog-cancel"),
  dialogConfirm: document.getElementById("dialog-confirm"),
  saveError: document.getElementById("save-error")
};

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayStr() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function monthOf(dateStr) {
  if (typeof dateStr !== "string" || dateStr.length < 7) return "";
  return dateStr.slice(0, 7);
}

function formatMoney(n) {
  const num = Number(n) || 0;
  const sign = num < 0 ? "-" : "";
  const abs = Math.abs(num);
  return sign + abs.toFixed(2);
}

function normalizeRecord(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = typeof raw.id === "string" && raw.id ? raw.id : "";
  if (!id) return null;
  const type = raw.type === "income" ? "income" : "expense";
  const amount = Number(raw.amount);
  return Object.assign({}, raw, {
    id: id,
    date: typeof raw.date === "string" ? raw.date : "",
    type: type,
    category: typeof raw.category === "string" ? raw.category : "",
    amount: isFinite(amount) ? amount : 0,
    note: typeof raw.note === "string" ? raw.note : ""
  });
}

function makeId() {
  return "r" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function showSaveError(msg) {
  state.saveError = msg || "";
  if (state.saveError) {
    el.saveError.textContent = state.saveError;
    el.saveError.hidden = false;
  } else {
    el.saveError.textContent = "";
    el.saveError.hidden = true;
  }
}

async function persist(nextRecords) {
  const prev = await appStore.getState();
  const next = Object.assign({}, prev, { records: nextRecords });
  try {
    await appStore.setState(next);
    showSaveError("");
    return true;
  } catch (err) {
    showSaveError("保存失败，数据未写入，请重试。");
    return false;
  }
}

function renderCategoryOptions() {
  const seen = [];
  state.records.forEach(function (r) {
    const c = (r.category || "").trim();
    if (c && seen.indexOf(c) === -1) seen.push(c);
  });
  seen.sort(function (a, b) { return a.localeCompare(b, "zh-Hans-CN"); });
  el.categoryList.textContent = "";
  seen.forEach(function (c) {
    const opt = document.createElement("option");
    opt.value = c;
    el.categoryList.appendChild(opt);
  });
}

function getFiltered() {
  const list = state.records.filter(function (r) {
    if (!state.filterMonth) return true;
    return monthOf(r.date) === state.filterMonth;
  });
  list.sort(function (a, b) {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });
  return list;
}

function renderStats(list) {
  let income = 0;
  let expense = 0;
  list.forEach(function (r) {
    if (r.type === "income") income += r.amount;
    else expense += r.amount;
  });
  const balance = income - expense;
  el.statIncome.textContent = formatMoney(income);
  el.statExpense.textContent = formatMoney(expense);
  el.statBalance.textContent = formatMoney(balance);
  el.statBalance.classList.toggle("negative", balance < 0);
}

function renderList() {
  const list = getFiltered();
  renderStats(list);

  el.listHint.textContent = state.filterMonth
    ? "当前筛选：" + state.filterMonth + "，共 " + list.length + " 条记录"
    : "全部记录，共 " + list.length + " 条";

  el.list.textContent = "";
  list.forEach(function (r) {
    const li = document.createElement("li");
    li.className = "record-item";

    const main = document.createElement("div");
    main.className = "rec-main";

    const top = document.createElement("div");
    top.className = "rec-top";

    const dateSpan = document.createElement("span");
    dateSpan.className = "rec-date";
    dateSpan.textContent = r.date || "无日期";
    top.appendChild(dateSpan);

    const catSpan = document.createElement("span");
    catSpan.className = "rec-cat";
    catSpan.textContent = (r.category || "未分类") + " · " + (r.type === "income" ? "收入" : "支出");
    top.appendChild(catSpan);

    main.appendChild(top);

    const note = document.createElement("div");
    note.className = "rec-note" + (r.note ? "" : " empty-note");
    note.textContent = r.note ? r.note : "（无备注）";
    main.appendChild(note);

    li.appendChild(main);

    const amount = document.createElement("span");
    amount.className = "rec-amount " + (r.type === "income" ? "income" : "expense");
    amount.textContent = (r.type === "income" ? "+" : "-") + formatMoney(r.amount);
    li.appendChild(amount);

    const del = document.createElement("button");
    del.type = "button";
    del.className = "rec-del";
    del.textContent = "删除";
    del.addEventListener("click", function () {
      openDeleteDialog(r);
    });
    li.appendChild(del);

    el.list.appendChild(li);
  });

  el.emptyTip.hidden = list.length !== 0;
}

function renderAll() {
  renderCategoryOptions();
  renderList();
}

function setFormError(msg) {
  el.formError.textContent = msg || "";
}

function resetForm() {
  el.date.value = todayStr();
  el.type.value = "expense";
  el.category.value = "";
  el.amount.value = "";
  el.note.value = "";
  setFormError("");
}

async function handleAdd() {
  setFormError("");

  const date = el.date.value;
  const type = el.type.value === "income" ? "income" : "expense";
  const category = el.category.value.trim();
  const amountRaw = el.amount.value.trim();
  const note = el.note.value.trim();

  if (!date) {
    setFormError("请选择日期。");
    return;
  }
  if (!category) {
    setFormError("请填写分类。");
    return;
  }
  if (amountRaw === "") {
    setFormError("请填写金额。");
    return;
  }
  const amount = Number(amountRaw);
  if (!isFinite(amount) || amount <= 0) {
    setFormError("金额必须是大于 0 的数字。");
    return;
  }
  const rounded = Math.round(amount * 100) / 100;

  const record = {
    id: makeId(),
    date: date,
    type: type,
    category: category,
    amount: rounded,
    note: note
  };

  const nextRecords = state.records.concat([record]);
  const ok = await persist(nextRecords);
  if (!ok) {
    return;
  }
  state.records = nextRecords;
  resetForm();
  renderAll();
}

let pendingDeleteId = null;

function openDeleteDialog(record) {
  pendingDeleteId = record.id;
  el.dialogText.textContent =
    "确定删除这条记录吗？" +
    (record.date || "无日期") + " " +
    (record.category || "未分类") + " " +
    (record.type === "income" ? "收入 " : "支出 ") +
    formatMoney(record.amount) + " 元。删除后无法恢复。";
  el.dialogMask.hidden = false;
  el.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  el.dialogMask.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }
  const nextRecords = state.records.filter(function (r) { return r.id !== id; });
  const ok = await persist(nextRecords);
  if (!ok) {
    closeDeleteDialog();
    return;
  }
  state.records = nextRecords;
  closeDeleteDialog();
  renderAll();
}

async function init() {
  const raw = await appStore.getState();
  const stored = raw && Array.isArray(raw.records) ? raw.records : [];
  state.records = stored.map(normalizeRecord).filter(function (r) { return r !== null; });

  resetForm();
  el.month.value = "";
  state.filterMonth = "";

  el.btnAdd.addEventListener("click", function () {
    handleAdd();
  });

  el.btnReset.addEventListener("click", function () {
    resetForm();
  });

  el.month.addEventListener("change", function () {
    state.filterMonth = el.month.value || "";
    renderList();
  });

  el.btnAllMonths.addEventListener("click", function () {
    el.month.value = "";
    state.filterMonth = "";
    renderList();
  });

  el.dialogCancel.addEventListener("click", function () {
    closeDeleteDialog();
  });

  el.dialogConfirm.addEventListener("click", function () {
    confirmDelete();
  });

  el.dialogMask.addEventListener("click", function (e) {
    if (e.target === el.dialogMask) {
      closeDeleteDialog();
    }
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !el.dialogMask.hidden) {
      closeDeleteDialog();
    }
  });

  renderAll();
}

await init();

artifact.css:
* { box-sizing: border-box; }

.app {
  max-width: 860px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #1f2937;
  font-size: 15px;
  line-height: 1.5;
}

.app-header { margin-bottom: 18px; }
.app-header h1 { margin: 0 0 4px; font-size: 24px; letter-spacing: 0.5px; }
.subtitle { margin: 0; color: #6b7280; font-size: 13px; }

.card {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 18px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.card-title { margin: 0 0 12px; font-size: 16px; font-weight: 600; }

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.field { display: flex; flex-direction: column; gap: 6px; }
.field-wide { grid-column: 1 / -1; }
.field label { font-size: 13px; color: #4b5563; font-weight: 500; }

input[type="text"],
input[type="number"],
input[type="date"],
input[type="month"],
select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font-size: 14px;
  color: #111827;
  background: #fff;
  font-family: inherit;
}

input:focus, select:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.form-error {
  margin: 10px 0 0;
  color: #b91c1c;
  font-size: 13px;
  min-height: 18px;
}

.form-actions { display: flex; gap: 10px; margin-top: 12px; flex-wrap: wrap; }

.btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.btn-primary { background: #2563eb; color: #fff; }
.btn-primary:hover { background: #1d4ed8; }

.btn-ghost { background: #f9fafb; color: #374151; border-color: #d1d5db; }
.btn-ghost:hover { background: #f3f4f6; }

.btn-danger { background: #dc2626; color: #fff; }
.btn-danger:hover { background: #b91c1c; }

.btn-sm { padding: 6px 12px; font-size: 13px; }

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.toolbar .card-title { margin: 0; }
.toolbar-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.toolbar-right input[type="month"] { width: 160px; }
.inline-label { font-size: 13px; color: #4b5563; }

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.stat {
  border-radius: 10px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  border: 1px solid #e5e7eb;
  background: #f9fafb;
}
.stat-label { font-size: 12px; color: #6b7280; }
.stat-value { font-size: 18px; font-weight: 600; font-variant-numeric: tabular-nums; }
.stat-income .stat-value { color: #047857; }
.stat-expense .stat-value { color: #b91c1c; }
.stat-balance .stat-value { color: #1d4ed8; }
.stat-balance .stat-value.negative { color: #b91c1c; }

.list-hint { margin: 0 0 8px; font-size: 12px; color: #6b7280; }

.record-list { list-style: none; margin: 0; padding: 0; }

.record-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 4px;
  border-bottom: 1px solid #f1f5f9;
}
.record-item:last-child { border-bottom: none; }

.rec-main { flex: 1; min-width: 0; }
.rec-top { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.rec-date { font-size: 12px; color: #6b7280; font-variant-numeric: tabular-nums; }
.rec-cat {
  font-size: 12px;
  padding: 1px 8px;
  border-radius: 999px;
  background: #eef2ff;
  color: #3730a3;
}
.rec-note { font-size: 13px; color: #4b5563; margin-top: 2px; word-break: break-word; }
.rec-note.empty-note { color: #9ca3af; }

.rec-amount {
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.rec-amount.income { color: #047857; }
.rec-amount.expense { color: #b91c1c; }

.rec-del {
  border: 1px solid #fecaca;
  background: #fff;
  color: #b91c1c;
  border-radius: 8px;
  padding: 5px 10px;
  font-size: 13px;
  cursor: pointer;
  font-family: inherit;
}
.rec-del:hover { background: #fef2f2; }

.empty { text-align: center; color: #9ca3af; font-size: 14px; padding: 24px 0; margin: 0; }

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}
.dialog-mask[hidden] { display: none; }

.dialog {
  background: #fff;
  border-radius: 12px;
  padding: 18px;
  width: 100%;
  max-width: 360px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.25);
}
.dialog-title { margin: 0 0 8px; font-size: 16px; }
.dialog-text { margin: 0 0 16px; font-size: 14px; color: #4b5563; word-break: break-word; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; }

.save-error {
  margin: 0;
  padding: 10px 12px;
  border-radius: 8px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  font-size: 13px;
}
.save-error[hidden] { display: none; }

@media (max-width: 520px) {
  .stats { grid-template-columns: 1fr; }
  .record-item { flex-wrap: wrap; }
  .rec-amount { margin-left: auto; }
}
